mapper.select:
SELECT * from (SELECT cri.change_req_id, cri.document_version_id, cri.status, cri.change_req_date, cri.change_req_user_id, cri.change_description, cri.document_id, cri.document_category, cri.document_type, cri.business_type, con.contract_id, con.project_id, (select t.ref_project_id from prj_project t where t.project_id=con.project_id)contract_id_bef, con.contract_number, con.contract_name, hbm.bp_name, con.CREATED_BY, con.contract_status, (select cc.contract_id from con_contract cc where cc.ref_contract_id= cri.document_id and cc.data_class='HISTORY' and cc.change_req_id=cri.change_req_id and rownum=1)history_contract_id, (select cc.project_id from con_contract cc where cc.ref_contract_id= cri.document_id and cc.data_class='HISTORY' and cc.change_req_id=cri.change_req_id and rownum=1)history_project_id FROM change_req_info cri, hls_bp_master hbm, con_contract con con.change_req_id = cri.change_req_id AND con.company_id = #{companyId} AND con.tenant_id = hbm.bp_id AND con.data_class = 'CHANGE_REQ' AND cri.document_category='CON_CONTRACT'
AND ( con.contract_number LIKE concat(concat('%',#{contractName}),'%') OR con.contract_name LIKE concat(concat('%',#{contractName}),'%') OR hbm.bp_name LIKE concat(concat('%',#{contractName}),'%'))
AND cri.change_req_date BETWEEN #{changeReqDateFrom} AND #{changeReqDateTo}
AND cri.status IN
#{status}
AND cri.business_type=#{businessType}
) t1 where 1=1 and (t1.CREATED_BY = #{request.userId} OR 10001 = #{request.userId} ) order by t1.change_req_id desc

select tab.* from ( select fp.project_id, fp.company_id, fp.contract_number, fp.contract_name, ( select fc.contract_id from fct_contract fc where fc.project_id = fp.project_id)contract_id, ( select case when cr.status = 'APPROVED' then (select fc.contract_id from fct_contract fc where fc.project_id = fp.project_id and fc.change_req_id = cri.change_req_id and fc.data_class = 'HISTORY') else ( select fc.ref_contract_id from fct_contract fc where fc.project_id = fp.project_id and fc.change_req_id = cri.change_req_id and fc.data_class = 'CHANGE_REQ') END from change_req_info cr where cr.change_req_id = cri.change_req_id )contract_id_bef, ( select fpq.quotataion_id from fct_project_quotation fpq where fpq.project_id = fp.project_id and rownum=1 )quotation_id, ( SELECT hbm.bp_name FROM fct_project_bp fpb, hls_bp_master hbm WHERE fp.project_id = fpb.project_id AND fpb.bp_id = hbm.bp_id and fpb.credit_grantor_party='Y' -- and fpb.repay_guarantee_party != 'Y' ) AS bp_name, ( SELECT hds.description FROM hls_document_status hds WHERE hds.status_code = cri.status AND hds.document_category = fp.document_category ) AS status_desc, cri.* from fct_project fp, change_req_info cri where fp.change_req_id = cri.change_req_id and fp.data_type = "CHANGE_REQ" and fp.data_class = "VIRTUAL_CON" )tab where 1 = 1 and (tab.CREATED_BY = #{request.userId} or 10001=#{request.userId} )
AND tab.status IN
#{item}
and tab.change_req_date = #{changeReqDate}
and tab.business_type = #{businessType}
and ((tab.contract_number like concat(concat('%',#{params}),'%')) or (tab.contract_name like concat(concat('%',#{params}),'%')) or (tab.bp_name like concat(concat('%',#{params}),'%')))
order by to_char(tab.change_req_date,'YYYY-MM-DD') desc,last_update_date desc

 select c.*,
 (
 select hds.description
 from hls_document_status hds
 where hds.status_code = c.status

     and hds.document_category = #{documentCategory}

 )status_desc,
/* (
 select fe.name from  fnd_employee fe,
 sys_user su
 where fe.employee_id=su.employee_id
 and c.change_req_user_id=su.user_id
 ) user_name*/
 (
 select distinct fe.name
 from sys_user_allocation sua,
 fnd_employee fe,
 fnd_employee_assigns fea
 where fe.employee_id = fea.employee_id
 and fea.employee_assign_id = sua.employee_assign_id
 and sua.user_id = c.change_req_user_id
 and sua.company_id = #{request.companyId}
 and fea.employee_assign_id = (select min(su.employee_assign_id)
 from sys_user_allocation su
 where su.user_id = c.change_req_user_id
 and su.company_id = #{request.companyId}
 )
 )user_name
 from change_req_info c
 where
 1 = 1

     and c.document_id = #{documentId}


     and c.document_category = #{documentCategory}

 order by c.change_req_id desc

select
c.*,su.description as user_name
from change_req_info c,
sys_user su

    su.user_id=c.change_req_user_id

        and c.document_id=#{documentId}


        and c.status=#{status}


        and c.document_category=#{documentCategory}
